134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        String idempotencyKey = idempotencyKey();
138	        if (idempotencyKey != null) {
139	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
140	            if (replay != null) {
141	                return replay;
142	            }
143	        }
144	        Owner owner = createOwner(ownerFieldsDto);
145	        if (idempotencyKey != null) {
146	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
147	        }
148	        return createdOwnerResponse(owner);
149	    }
150	
151	    /**
152	     * Reads the request's {@code Idempotency-Key} header, returning the trimmed key or {@code null}
153	     * when the header is absent or blank. A blank key carries no intent to deduplicate, so the
154	     * create proceeds normally.
155	     *
156	     * @return the non-blank idempotency key, or {@code null} when none was supplied
157	     */
158	    private String idempotencyKey() {
159	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
160	        if (key == null || key.isBlank()) {
161	            return null;
162	        }
163	        return key.trim();
164	    }
165	
166	    /**
167	     * Replays the create originally produced by the given {@code Idempotency-Key}, if any: when the
168	     * key has already created an owner that still exists, that owner is rendered with {@code 200 OK}
169	     * (rather than creating a duplicate with {@code 201 Created}). When the key has not been seen, or
170	     * the owner it created no longer exists, {@code null} is returned so the caller creates the owner
171	     * normally.
172	     *
173	     * @param idempotencyKey the non-blank idempotency key supplied on the request
174	     * @return the {@code 200 OK} response carrying the originally created owner, or {@code null}
175	     */
176	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
177	        Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
178	        if (existingId == null) {
179	            return null;
180	        }
181	        Owner existing = this.clinicService.findOwnerById(existingId);
182	        if (existing == null) {
183	            return null;
184	        }
185	        return okOwnerResponse(existing);
186	    }
187	
188	    /**
189	     * Runs the full intake pipeline for a newly submitted owner and persists the result, returning
190	     * the saved {@link Owner}. The submitted fields are normalized and validated
191	     * ({@link #prepareNewOwner(OwnerFieldsDto, LocalDate)}) against the effective business-day
192	     * {@code registrationDate} ({@link #effectiveRegistrationDate(OwnerFieldsDto)}); the owner is
193	     * then mapped, stamped with that registration date and every derived value (customer code,
194	     * namesake count, household), flagged as a possible duplicate where applicable, saved, and
195	     * finally stamped with its household member count. A rule that rejects the owner signals it by
196	     * throwing, which the exception advice renders as the matching 4xx response, so this method
197	     * returns only for an owner that was accepted and persisted. The create is audited once the
198	     * owner has its identity.
199	     *
200	     * <p>The returned owner carries its generated id and every stored field, ready to be rendered by
201	     * {@link #createdOwnerResponse(Owner)}.
202	     *
203	     * @param ownerFieldsDto the submitted owner fields, normalized in place
204	     * @return the persisted owner
205	     */
206	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
207	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
208	        prepareNewOwner(ownerFieldsDto, registrationDate);
209	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
210	        owner.setRegistrationDate(registrationDate);
211	        owner.setCustomerCode(customerCodeFor(owner));
212	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
213	        assignHousehold(owner);
214	        applyPossibleDuplicate(owner, ownerFieldsDto);
215	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
216	        this.clinicService.saveOwner(owner);
217	        applyHouseholdMemberCount(owner);
218	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
219	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
220	            owner.getMembershipLevel(), owner.getMembershipNumber());
221	        return owner;
222	    }
223	
224	    /**
225	     * Renders a persisted owner as the {@code 201 Created} response of the create endpoint. The owner
226	     * is mapped to an {@link OwnerDto}, its {@code bulkSignupWarning} is derived from the owner's
227	     * stored {@code registrationDate} (mirroring {@link #getOwner(Integer)}), and a {@code Location}
228	     * header pointing at {@code /api/owners/{id}} is attached. Isolating the response assembly here
229	     * keeps {@link #addOwner(OwnerFieldsDto)} a thin orchestration of "create the owner, then render
230	     * it" and gives the created representation one place to grow.
231	     *
232	     * @param owner the persisted owner to render, carrying its generated id and stored fields
233	     * @return the {@code 201 Created} response carrying the owner representation and {@code Location} header
234	     */
235	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
236	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
237	        HttpHeaders headers = new HttpHeaders();
238	        headers.setLocation(UriComponentsBuilder.newInstance()
239	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
240	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
241	    }
242	
243	    /**
244	     * Renders a persisted owner as the {@code 200 OK} response shared by the read path
245	     * ({@link #getOwner(Integer)}) and the idempotent-replay path
246	     * ({@link #replayIdempotentCreate(String)}): the owner is stamped with its household member
247	     * count and then mapped to an {@link OwnerDto} carrying its {@code bulkSignupWarning} (see
248	     * {@link #toOwnerDtoWithWarning(Owner)}). Isolating the assembly here keeps both paths rendering
249	     * an existing owner identically rather than each copying the same steps.
250	     *
251	     * @param owner the persisted owner to render
252	     * @return the {@code 200 OK} response carrying the owner representation
253	     */
254	    private ResponseEntity<OwnerDto> okOwnerResponse(Owner owner) {
255	        applyHouseholdMemberCount(owner);
256	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
257	    }
258	
259	    /**
260	     * Maps a persisted owner to the {@link OwnerDto} returned by every rendered response, stamping
261	     * its {@code bulkSignupWarning} from the owner's stored {@code registrationDate} (see
262	     * {@link #bulkSignupWarning(LocalDate)}). This is the single definition of how an owner becomes
263	     * its response representation, shared by the read, idempotent-replay and create responses, so all
264	     * three derive the rendered fields identically rather than each copying the mapping.
265	     *
266	     * @param owner the persisted owner to map
267	     * @return the owner representation with its {@code bulkSignupWarning} set
268	     */
269	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
270	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
271	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
272	        return ownerDto;
273	    }
