371	    /**
372	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
373	     * The address is normalized in place (so a required-field check that follows rejects an
374	     * address blank after normalization), the required fields are checked, the telephone and
375	     * email are normalized in place, and the resulting owner is rejected when its derived
376	     * identity key already belongs to another owner. Each rule
377	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
378	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
379	     * to be mapped and saved.
380	     *
381	     * @param ownerFieldsDto the submitted owner fields, normalized in place
382	     */
383	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
384	        applyAddress(ownerFieldsDto);
385	        validateRequiredFields(ownerFieldsDto);
386	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
387	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
388	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
389	        rejectDuplicateIdentity(ownerFieldsDto);
390	        rejectCityAtCapacity(ownerFieldsDto.getCity());
391	        rejectDailyLimitExceeded(registrationDate);
392	    }
393	
394	    /**
395	     * Applies an owner's address to the submitted fields, normalizing it in place into the
396	     * canonical form stored and returned for the owner. This is the single intake step that owns
397	     * how a submitted address becomes an owner's stored address: it delegates every transform to
398	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
399	     * the results back onto {@code ownerFieldsDto}.
400	     *
401	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
402	     * is present the two structured lines are normalized in place and the flat {@code address} is
403	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
404	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
405	     * every rule that later reads {@code address} sees the structured value. When no structured
406	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
407	     * backward compatibility.
408	     *
409	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
410	     * blank after normalization in either form is rejected by the required-field check that
411	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
412	     * list of named intake steps and gives address handling one place to grow.
413	     *
414	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
415	     */
416	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
417	        String line1 = ownerFieldsDto.getAddressLine1();
418	        if (line1 != null && !line1.isBlank()) {
419	            String normalizedLine1 = normalizeAddress(line1);
420	            ownerFieldsDto.setAddressLine1(normalizedLine1);
421	            String line2 = ownerFieldsDto.getAddressLine2();
422	            if (line2 != null && !line2.isBlank()) {
423	                String normalizedLine2 = normalizeAddress(line2);
424	                ownerFieldsDto.setAddressLine2(normalizedLine2);
425	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
426	            } else {
427	                ownerFieldsDto.setAddressLine2(null);
428	                ownerFieldsDto.setAddress(normalizedLine1);
429	            }
430	        } else {
431	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
432	        }
433	    }
434	
435	    /**
436	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
437	     * falls on a business day. The date supplied on the request is used when present, otherwise the
438	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
439	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
440	     * is left unchanged. This single adjusted date
441	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
442	     * membership number's year segment, the per-day create limit) is computed against.
443	     *
444	     * A supplied registration date later than the server's current date is rejected with an
445	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
446	     *
447	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
448	     * @return the effective registration date rolled forward to the next business day
449	     */
450	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
451	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
452	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
453	            throw new InvalidFieldsException(List.of("registrationDate"));
454	        }
455	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
456	        return toBusinessDay(effective);
457	    }
458	
459	    /**
460	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
461	     * advanced, along with weekends, until it reaches the next non-holiday business day.
462	     */
463	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
464	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
465	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
466	        LocalDate.parse("2026-12-28"));
467	
468	    /**
469	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
470	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
471	     * date already on such a business day is returned unchanged.
472	     *
473	     * @param date the date to adjust
474	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
475	     */
476	    private LocalDate toBusinessDay(LocalDate date) {
477	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
478	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
479	                || PUBLIC_HOLIDAYS.contains(date)) {
480	            date = date.plusDays(1);
481	        }
482	        return date;
483	    }
484	
485	    /**
486	     * The maximum number of owners that may be created on a single day. Once this many owners
487	     * already carry today's {@code registrationDate}, no further owner may be created today.
488	     */
489	    private static final long DAILY_OWNER_LIMIT = 100L;
490	
491	    /**
492	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
493	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
494	     * date the new owner would be stored with, so owners are capped per business day. When the limit
495	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
496	     * advice renders as a 429 Too Many Requests response.
497	     *
498	     * @param registrationDate the adjusted business-day registration date of the owner being created
499	     */
500	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
501	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
502	            throw new DailyOwnerLimitExceededException(registrationDate);
503	        }
504	    }
505	
506	    /**
507	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
508	     * given date. This is the single definition of the per-day owner count, shared by the per-day
509	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
510	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
511	     *
512	     * @param registrationDate the adjusted business-day registration date to count owners against
513	     * @return the number of existing owners carrying that registration date
514	     */
515	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
516	        return this.clinicService.findAllOwners().stream()
517	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
518	            .count();
