567	    /**
568	     * Builds the customer code assigned to a newly created owner. The code is formatted as
569	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
570	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
571	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
572	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
573	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
574	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
575	     * identity scheme needs.
576	     *
577	     * @param owner the owner being created, whose fields the code is derived from
578	     * @return the formatted customer code
579	     */
580	    private String customerCodeFor(Owner owner) {
581	        String region = owner.getRegion();
582	        String regionCode = region != null ? region : "UNKNOWN";
583	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
584	        return deduplicateCustomerCode(regionCode + "-" + hash8);
585	    }
