587	    /**
588	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
589	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
590	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
591	     *
592	     * @param baseCode the customer code computed for the owner being created
593	     * @return the base code when it is already unique, otherwise the de-duplicated code
594	     */
595	    private String deduplicateCustomerCode(String baseCode) {
596	        Set<String> existing = this.clinicService.findAllOwners().stream()
597	            .map(Owner::getCustomerCode)
598	            .filter(Objects::nonNull)
599	            .collect(Collectors.toSet());
600	        if (!existing.contains(baseCode)) {
601	            return baseCode;
602	        }
603	        int n = 2;
604	        while (existing.contains(baseCode + "-" + n)) {
605	            n++;
606	        }
607	        return baseCode + "-" + n;
608	    }
