655	    /**
656	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
657	     * duplicate: a non-deleted owner whose {@code lastName} shares the new owner's Soundex code (see
658	     * {@link Owner#soundex(String)}) and whose {@code postcode} matches, while carrying a different
659	     * identity key (see {@link Owner#identityKey(String, String, String)}). Requiring a differing
660	     * identity key keeps a hard duplicate — already rejected with 409 by
661	     * {@link #rejectDuplicateIdentity(OwnerFieldsDto)} — from also being flagged as a soft match, so
662	     * the two household members whose telephones differ (hence differing identity keys, but matching
663	     * Soundex and postcode) are exactly the soft matches surfaced here. This is the single definition
664	     * of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records
665	     * the outcome on the owner. An owner without a postcode can share no postcode and matches nothing,
666	     * so {@link java.util.Optional#empty()} is returned.
667	     *
668	     * @param owner the owner being created, already carrying its normalized telephone and postcode
669	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
670	     */
671	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
672	        if (owner.getPostcode() == null) {
673	            return java.util.Optional.empty();
674	        }
675	        String soundex = Owner.soundex(owner.getLastName());
676	        String identityKey = owner.getIdentityKey();
677	        return this.clinicService.findAllOwners().stream()
678	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
679	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
680	                && soundex.equals(Owner.soundex(existing.getLastName()))
681	                && owner.getPostcode().equals(existing.getPostcode()))
682	            .findFirst();
683	    }
