685	    /**
686	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
687	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
688	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
689	     * the names of every offending field, which the exception advice renders as a 400 response
690	     * with an {@code errors} array.
691	     *
692	     * @param ownerFieldsDto the submitted owner fields
693	     */
694	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
695	        List<String> missing = new ArrayList<>();
696	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
697	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
698	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
699	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
700	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
701	        if (!missing.isEmpty()) {
702	            throw new RequiredFieldsMissingException(missing);
