712	    /**
713	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
714	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
715	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
716	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
717	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
718	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
719	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
720	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
721	     *
722	     * @param telephone the submitted telephone value
723	     * @return the normalized E.164 telephone
724	     */
725	    private String normalizeTelephone(String telephone) {
726	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
727	        String e164;
728	        if (cleaned.startsWith("+")) {
729	            e164 = "+" + cleaned.substring(1);
730	        } else {
731	            String national = cleaned;
732	            if (national.startsWith("0")) {
733	                national = national.substring(1);
734	            }
735	            e164 = "+61" + national;
736	        }
737	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
738	            throw new InvalidFieldsException(List.of("telephone"));
739	        }
740	        validateNationalNumberLength(e164);
741	        return e164;
742	    }
743	
744	    /**
745	     * Validates the national-number length of an already syntactically valid E.164 telephone
746	     * against its country code. When the number carries a country code this application recognizes
747	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
748	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
749	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
750	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
751	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
752	     * that is not recognized carries no per-country length rule and is left to the general
753	     * 8-to-15-digit E.164 check.
754	     *
755	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
756	     */
757	    private void validateNationalNumberLength(String e164) {
758	        String countryCode = Owner.countryCodeOf(e164);
759	        if (countryCode == null) {
760	            return;
761	        }
762	        int nationalLength = e164.length() - 1 - countryCode.length();
763	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
764	            throw new InvalidFieldsException(List.of("telephone"));
765	        }
766	    }
