768	    /**
769	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
770	     * and a domain containing at least one dot, none of the parts holding whitespace or a
771	     * second {@code @}.
772	     */
773	    private static final java.util.regex.Pattern EMAIL_PATTERN =
774	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
775	
776	    /**
777	     * Disposable email domains an owner may not register with. An email whose domain (compared
778	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
779	     */
780	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
781	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
782	
783	    /**
784	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
785	     * accepted and returned unchanged. When present it must be a syntactically valid address
786	     * whose domain is not on the disposable-domain blocklist (see
787	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
788	     * present but syntactically invalid or on a disposable domain an
789	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
790	     * response naming the {@code email} field.
791	     *
792	     * @param email the submitted email value, or {@code null} when omitted
793	     * @return the lower-cased email, or {@code null} when none was supplied
794	     */
795	    private String normalizeEmail(String email) {
796	        if (email == null) {
797	            return null;
798	        }
799	        String trimmed = email.trim();
800	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
801	            throw new InvalidFieldsException(List.of("email"));
802	        }
803	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
804	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
805	            throw new InvalidFieldsException(List.of("email"));
806	        }
807	        return canonicalEmail(trimmed);
808	    }
809	
810	    /**
811	     * Reduces an email to the canonical form used both to store it and to compare it against
812	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
813	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
814	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
815	     * value read back off an existing owner without risk of rejecting it. This is the single
816	     * definition of email identity: two emails denote the same address exactly when they
817	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
818	     * an email already on an existing owner can be compared for equality after both pass through
819	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
820	     *
821	     * @param email the email to canonicalize, or {@code null} when none was supplied
822	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
823	     */
824	    private String canonicalEmail(String email) {
825	        if (email == null) {
826	            return null;
827	        }
828	        return email.trim().toLowerCase(java.util.Locale.ROOT);
829	    }
