831	    /**
832	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
833	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
834	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
835	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
836	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
837	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
838	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
839	     * 400 response naming the {@code postcode} field.
840	     *
841	     * @param postcode the submitted postcode, or {@code null} when omitted
842	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
843	     */
844	    private void validatePostcode(String postcode, String city) {
845	        if (postcode == null) {
846	            return;
847	        }
848	        if (!postcode.matches("^[0-9]{4}$")) {
849	            throw new InvalidFieldsException(List.of("postcode"));
850	        }
851	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
852	        if (range != null) {
853	            int value = Integer.parseInt(postcode);
854	            if (value < range[0] || value > range[1]) {
855	                throw new InvalidFieldsException(List.of("postcode"));
856	            }
857	        }
858	    }
