860	    /**
861	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
862	     * identity is its single derived identity key (see
863	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
864	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
865	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
866	     * owner carries the same identity key. The email-domain blocklist has already been applied when
867	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
868	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
869	     * name and postcode) but carry different telephones now have distinct identity keys and are not
870	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
871	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
872	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
873	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
874	     * deliberate household member and bypasses this block.
875	     *
876	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
877	     */
878	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
879	        if (sharesHousehold(ownerFieldsDto)) {
880	            return;
881	        }
882	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
883	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
884	        boolean taken = this.clinicService.findAllOwners().stream()
885	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
886	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
887	        if (taken) {
888	            throw new DuplicateIdentityException(identityKey);
889	        }
890	    }
