918	    /**
919	     * Derives the stable {@code householdId} shared by every owner in the household identified by
920	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
921	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
922	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
923	     * postcode — regardless of creation order or address — resolve to the same identifier
924	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
925	     * returned.
926	     *
927	     * @param lastName the household's last name
928	     * @param postcode the household's postcode, or {@code null} when the owner has none
929	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
930	     */
931	    private String householdIdFor(String lastName, String postcode) {
932	        if (postcode == null) {
933	            return null;
934	        }
935	        return shaHex(householdKey(lastName, postcode), 12);
936	    }
