938	    /**
939	     * Builds the canonical household key that identifies the household a {@code lastName} and
940	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
941	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
942	     * owner fields make up a household and how they are normalized;
943	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
944	     * owners in the same household resolve to the same key and therefore the same identifier.
945	     *
946	     * @param lastName the household's last name
947	     * @param postcode the household's postcode
948	     * @return the normalized household key
949	     */
950	    private String householdKey(String lastName, String postcode) {
951	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
952	    }
