954	    /**
955	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
956	     * string, the form used by the derived owner codes (for example the customer code and household
957	     * identifier). The digest itself comes from {@link Owner#sha256Hex(String)}, the single
958	     * definition of the SHA-256 hex derivation; this method only takes its leading characters and
959	     * upper-cases them, so {@code hexChars} characters cover the leading {@code ceil(hexChars / 2)}
960	     * bytes of the digest.
961	     *
962	     * @param input the string to hash
963	     * @param hexChars the number of leading upper-case hex characters to return
964	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
965	     */
966	    private String shaHex(String input, int hexChars) {
967	        return Owner.sha256Hex(input).substring(0, hexChars).toUpperCase(java.util.Locale.ROOT);
968	    }
