970	    /**
971	     * Returns the owners that belong to the household identified by the given {@code householdId},
972	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
973	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
974	     * filters them out itself. The owners are taken from the current set, so after a create the
975	     * result includes the newly persisted owner. An owner without a household (a {@code null}
976	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
977	     * definition of a household's members, shared by every rule that reasons about the owners
978	     * sharing a household (the household-duplicate block and the household member count).
979	     *
980	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
981	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
982	     */
983	    private List<Owner> householdMembers(String householdId) {
984	        if (householdId == null) {
985	            return List.of();
986	        }
987	        return this.clinicService.findAllOwners().stream()
988	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
989	            .collect(Collectors.toList());
