995	     * is taken against the current set of owners, so after a create it reflects the household's size
996	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
997	     * belongs to no shared household and yields {@code 0}.
998	     *
999	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1000	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1001	     */
1002	    private int countHouseholdMembers(String householdId) {
1003	        return householdMembers(householdId).size();
1004	    }
1005	
1006	    /**
1007	     * Stamps an owner with its household member count, the number of owners sharing its household
1008	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1009	     * household size (its membership factor and level) reads a populated count rather than the
1010	     * unstamped default. This is the single definition of hydrating an owner with its household
1011	     * member count, shared by the create and read paths that render an owner's derived values.
1012	     *
1013	     * @param owner the owner to stamp, mutated in place with its household member count
1014	     */
1015	    private void applyHouseholdMemberCount(Owner owner) {
1016	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1017	    }
1018	
1019	    /**
1020	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1021	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1022	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1023	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1024	     * reads a populated count, mirroring how the create and read paths render a member's derived
1025	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1026	     * members already in the household. When the owner joins an empty household — no household
1027	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1028	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1029	     *
1030	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1031	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1032	     */
1033	    private Integer householdMembershipLevelCap(String householdId) {
1034	        java.util.OptionalInt max = householdMembers(householdId).stream()
1035	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1036	            .peek(this::applyHouseholdMemberCount)
1037	            .mapToInt(Owner::getMembershipLevel)
1038	            .max();
1039	        return max.isPresent() ? max.getAsInt() + 1 : null;
1040	    }
1041	
1042	    /**
1043	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1044	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1045	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1046	     *
1047	     * @param value the value to collapse, or {@code null}
1048	     * @return the whitespace-collapsed value, never {@code null}
1049	     */
1050	    private String collapseWhitespace(String value) {
1051	        if (value == null) {
1052	            return "";
1053	        }
1054	        return value.trim().replaceAll("\\s+", " ");
1055	    }
1056	
1057	    /**
1058	     * Common street-type abbreviations expanded during address normalization, keyed by their
1059	     * upper-cased token.
1060	     */
1061	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1062	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1063	
1064	    /**
1065	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1066	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1067	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1068	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1069	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1070	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1071	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1072	     * everywhere an address is stored or compared.
1073	     *
1074	     * @param address the submitted address value, or {@code null}
1075	     * @return the normalized address, never {@code null}
1076	     */
1077	    private String normalizeAddress(String address) {
1078	        if (address == null) {
1079	            return "";
1080	        }
1081	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1082	        if (collapsed.isEmpty()) {
1083	            return "";
1084	        }
1085	        String[] tokens = collapsed.split(" ");
1086	        StringBuilder sb = new StringBuilder(collapsed.length());
1087	        for (int i = 0; i < tokens.length; i++) {
1088	            if (i > 0) {
1089	                sb.append(' ');
1090	            }
1091	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1092	        }
1093	        return sb.toString();
1094	    }
1095	}
